export declare const salesAlert = "\n<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Achat Confirm\u00E9</title>\n\n<style>\n    body{\n        margin:0;\n        padding:0;\n        background-color:#f3f4f6;\n        font-family:Arial, Helvetica, sans-serif;\n        color:#111827;\n    }\n\n    .wrapper{\n        width:100%;\n        padding:40px 20px;\n        box-sizing:border-box;\n    }\n\n    .container{\n        max-width:620px;\n        margin:0 auto;\n        background:#ffffff;\n        border:1px solid #e5e7eb;\n        border-radius:10px;\n        overflow:hidden;\n    }\n\n    .header{\n        padding:28px 32px;\n        border-bottom:1px solid #e5e7eb;\n        background:#ffffff;\n    }\n\n    .header h1{\n        margin:0;\n        font-size:22px;\n        font-weight:600;\n        color:#111827;\n    }\n\n    .header p{\n        margin:8px 0 0;\n        font-size:14px;\n        color:#6b7280;\n    }\n\n    .content{\n        padding:32px;\n    }\n\n    .content p{\n        margin:0 0 18px;\n        line-height:1.7;\n        font-size:15px;\n        color:#374151;\n    }\n\n    .info-box{\n        margin:28px 0;\n        border:1px solid #e5e7eb;\n        border-radius:8px;\n        overflow:hidden;\n    }\n\n    .info-row{\n        display:flex;\n        padding:14px 18px;\n        border-bottom:1px solid #e5e7eb;\n        font-size:14px;\n    }\n\n    .info-row:last-child{\n        border-bottom:none;\n    }\n\n    .label{\n        width:190px;\n        font-weight:600;\n        color:#111827;\n    }\n\n    .value{\n        flex:1;\n        color:#4b5563;\n    }\n\n    .notice{\n        margin-top:30px;\n        padding-top:20px;\n        border-top:1px solid #e5e7eb;\n        font-size:14px;\n        line-height:1.7;\n        color:#6b7280;\n    }\n\n    .footer{\n        padding:20px 32px;\n        background:#f9fafb;\n        border-top:1px solid #e5e7eb;\n        font-size:12px;\n        color:#9ca3af;\n        text-align:center;\n    }\n\n    @media only screen and (max-width:600px){\n\n        .content,\n        .header,\n        .footer{\n            padding:24px;\n        }\n\n        .info-row{\n            display:block;\n        }\n\n        .label{\n            width:100%;\n            margin-bottom:6px;\n        }\n    }\n</style>\n</head>\n\n<body>\n\n<div class=\"wrapper\">\n\n    <div class=\"container\">\n\n        <!-- Header -->\n        <div class=\"header\">\n            <h1>Achat confirm\u00E9</h1>\n            <p>Notification interne de la plateforme</p>\n        </div>\n\n        <!-- Content -->\n        <div class=\"content\">\n\n            <p>Bonjour Administrateur,</p>\n\n            <p>\n                Un achat a \u00E9t\u00E9 effectu\u00E9 avec succ\u00E8s sur la plateforme.\n                Les d\u00E9tails de la transaction sont disponibles ci-dessous.\n            </p>\n\n            <!-- Information Box -->\n            <div class=\"info-box\">\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Soci\u00E9t\u00E9</div>\n                    <div class=\"value\">%tenant_name%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Pack achet\u00E9</div>\n                    <div class=\"value\">%pack_name%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Montant</div>\n                    <div class=\"value\">%amount%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">R\u00E9f\u00E9rence paiement</div>\n                    <div class=\"value\">%payment_ref%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Nouveau solde</div>\n                    <div class=\"value\">%new_balance%</div>\n                </div>\n\n            </div>\n\n            <div class=\"notice\">\n                Cette notification confirme qu\u2019une transaction a \u00E9t\u00E9 valid\u00E9e\n                et que le solde du compte client a \u00E9t\u00E9 mis \u00E0 jour automatiquement.\n            </div>\n\n        </div>\n\n        <!-- Footer -->\n        <div class=\"footer\">\n            \u00A9 %current_year% Plateforme SaaS SMS Marketing \u2014 Tous droits r\u00E9serv\u00E9s\n        </div>\n\n    </div>\n\n</div>\n\n</body>\n</html>\n";
